SELECT
id, student_code, real_name, birth_date, admission_year, major,
academic_status, description, sys_user_id, create_time, update_time
FROM
mg_student


        AND student_code LIKE CONCAT('%', #{studentCode}, '%')


        AND real_name LIKE CONCAT('%', #{realName}, '%')


        AND admission_year = #{admissionYear}


        AND major LIKE CONCAT('%', #{major}, '%')


        AND academic_status = #{academicStatus}




                AND create_time >= #{startTime}


                AND create_time <= #{endTime}


                AND create_time BETWEEN #{startTime} AND #{endTime}



    AND is_deleted = 0


    ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}


    ORDER BY create_time DESC
